"""Meridian payments API client with pagination, ETag, rate-limit and idempotency support."""

from __future__ import annotations

import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from typing import Any

import requests


class MeridianClient:
    """HTTP client for the Meridian payments API with pagination, ETag, rate-limit, and idempotency support."""

    def __init__(self, base_url: str, api_key: str) -> None:
        self._base = base_url.rstrip("/")
        self._api_key = api_key
        self._etag: str | None = None

    # ------------------------------------------------------------------ helpers
    @property
    def _auth_headers(self) -> dict[str, str]:
        return {"Authorization": f"Bearer {self._api_key}"}

    def _with_etag(self, headers: dict[str, str]) -> dict[str, str]:
        if self._etag:
            headers = {**headers, "If-None-Match": self._etag}
        return headers

    def _handle_429(self, resp: requests.Response) -> requests.Response:
        """Sleep per Retry-After header and re-issue the request. Raises on other errors."""
        retry_after = resp.headers.get("Retry-After")
        if not retry_after:
            raise RuntimeError("429 without Retry-After")
        # integer seconds or HTTP-date
        try:
            wait = int(retry_after)
        except ValueError:
            dt = parsedate_to_datetime(retry_after)
            wait = max(0, (dt - datetime.now(timezone.utc)).total_seconds())
        time.sleep(wait)
        # Re-issue the same request (we need the original method/headers/body)
        return resp.request  # type: ignore[return-value]

    def _request(self, method: str, path: str, **kwargs: Any) -> requests.Response:
        """Execute a request with auth, ETag, and 429 retry logic."""
        headers = self._with_etag({**self._auth_headers, **(kwargs.pop("headers", {}))})
        kwargs["headers"] = headers

        resp = requests.request(method, f"{self._base}{path}", **kwargs)

        if resp.status_code == 304:
            # Store ETag for future use
            self._etag = resp.headers.get("ETag", self._etag)
            return resp

        if resp.status_code == 429:
            # Sleep and retry once
            new_kwargs = {**kwargs}
            new_kwargs["headers"] = headers
            time.sleep(0)  # handled below
            retry_after = resp.headers.get("Retry-After")
            if not retry_after:
                raise RuntimeError("429 without Retry-After")
            try:
                wait = int(retry_after)
            except ValueError:
                dt = parsedate_to_datetime(retry_after)
                wait = max(0, (dt - datetime.now(timezone.utc)).total_seconds())
            time.sleep(wait)
            resp = requests.request(method, f"{self._base}{path}", **new_kwargs)

        # Update ETag if present in successful response
        etag = resp.headers.get("ETag")
        if etag:
            self._etag = etag

        return resp

    def _normalize_created_at(self, payment: dict[str, Any]) -> None:
        """Convert created_at to UTC ISO format in-place."""
        raw = payment.get("created_at", "")
        if raw:
            dt = datetime.fromisoformat(raw).astimezone(timezone.utc)
            payment["created_at"] = dt.isoformat()

    # --------------------------------------------------------------- public API
    def fetch_all_payments(self) -> list[dict]:
        """Cursor-paginate GET /v1/payments, accumulating data until next_cursor is null."""
        all_payments: list[dict] = []
        cursor: str | None = None

        while True:
            params: dict[str, Any] = {"limit": 100}
            if cursor is not None:
                params["cursor"] = cursor

            resp = self._request("GET", "/v1/payments", params=params)

            # 304 → nothing new
            if resp.status_code == 304:
                return []

            body = resp.json()

            # 410 Gone — cursor expired, discard and restart from page 1
            if resp.status_code == 410:
                all_payments.clear()
                self._etag = None
                cursor = None
                continue

            data = body.get("data", [])
            for p in data:
                self._normalize_created_at(p)
                all_payments.append(p)

            next_cursor = body.get("next_cursor")
            if next_cursor is None:
                break
            cursor = next_cursor

        # Sort oldest-first by actual UTC instant, not string comparison
        all_payments.sort(key=lambda p: datetime.fromisoformat(p["created_at"]))
        return all_payments

    def total_count(self) -> int:
        """Hit the first page of /v1/payments (limit=1) and return the total field."""
        resp = self._request("GET", "/v1/payments", params={"limit": 1})
        if resp.status_code == 304:
            return 0
        body = resp.json()
        return body.get("total", 0)

    def create_payment(
        self,
        amount_minor: int,
        currency: str,
        idempotency_key: str,
    ) -> str:
        """POST /v1/payments. 201 → payment_id; 409 → duplicate, return payment_id."""
        headers = {**self._auth_headers, "Idempotency-Key": idempotency_key}
        body = {"amount_minor": amount_minor, "currency": currency}

        resp = requests.post(
            f"{self._base}/v1/payments",
            json=body,
            headers=headers,
        )

        if resp.status_code == 429:
            retry_after = resp.headers.get("Retry-After")
            if not retry_after:
                raise RuntimeError("429 without Retry-After")
            try:
                wait = int(retry_after)
            except ValueError:
                dt = parsedate_to_datetime(retry_after)
                wait = max(0, (dt - datetime.now(timezone.utc)).total_seconds())
            time.sleep(wait)
            resp = requests.post(
                f"{self._base}/v1/payments",
                json=body,
                headers=headers,
            )

        result = resp.json()
        payment_id = result.get("payment_id", "")

        if resp.status_code == 201:
            return payment_id
        if resp.status_code == 409:
            return payment_id
        raise RuntimeError(f"create_payment failed: {resp.status_code} {result}")
